package com.eia.contract.expert.cashcall;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Create payload for a contract cash call.
 *
 * <p>The call number is generated by the expert ({@code CC-{YEAR}-{SEQ}}) and the
 * status always starts at {@code REQUESTED}, so neither is accepted from the
 * caller. The amount is a decimal JSON value (a JSON number or a decimal string
 * both deserialize to {@link BigDecimal}) and must be greater than zero.</p>
 */
public record CreateCashCallRequest(
        LocalDate periodStart,
        LocalDate periodEnd,
        BigDecimal amount,
        String currency,
        LocalDate dueDate,
        String notes
) {}
